section "mod-tome/class/uiset/Classic.lua"

t([[Displaying talents (#{bold}##GOLD#%s#LAST##{normal}#)
Toggle for creature display]], [[タレント表示(#{bold}##GOLD#%s#LAST##{normal}#)
　キャラクタ－表示設定に切り替えます]], "tformat")
t([[Displaying creatures (#{bold}##GOLD#%s#LAST##{normal}#)
Toggle for talent display#]], [[キャラクター表示(#{bold}##GOLD#%s#LAST##{normal}#)
　タレント表示設定に切り替えます#]], "tformat")
t("#{bold}##GOLD#I#LAST##{normal}#nventory", "#{bold}##GOLD#インベントリ#LAST##{normal}#", "_t")
t("Inventory (#{bold}##GOLD#%s#LAST##{normal}#)", "インベントリ(#{bold}##GOLD#%s#LAST##{normal}#)", "tformat")
t("#{bold}##GOLD#C#LAST##{normal}#haracter Sheet", "#{bold}##GOLD#キャラクターシート#LAST##{normal}#", "_t")
t("Character Sheet (#{bold}##GOLD#%s#LAST##{normal}#)", "キャラクターシート(#{bold}##GOLD#%s#LAST##{normal}#)", "tformat")
t("Main menu (#{bold}##GOLD#%s#LAST##{normal}#)", "メインメニュー(#{bold}##GOLD#%s#LAST##{normal}#)", "tformat")
t("Show message/chat log (#{bold}##GOLD#%s#LAST##{normal}#)", "メッセージ／チャットログ表示(#{bold}##GOLD#%s#LAST##{normal}#)", "tformat")
t([[Movement: #LIGHT_GREEN#Default#LAST# (#{bold}##GOLD#%s#LAST##{normal}#)
Toggle for passive mode]], [[移動モード：#LIGHT_GREEN#デフォルト#LAST# (#{bold}##GOLD#%s#LAST##{normal}#)
　移動モード：パッシブに切り替えます]], "tformat")
