------------------------------------------------
section "mod-tome/data/chats/artifice-mastery.lua"

t("Cancel", "キャンセル", "_t")
t("#CADET_BLUE#%s already mastered.", "#CADET_BLUE#%sはマスター済みだ。", "log")
t("#LIGHT_BLUE# You enhance your preparation of %s.", "#LIGHT_BLUE#%sを強化した。", "log")
t("%s[%s -- mastery: %s]#LAST#", "%s（%s　強化版：%s）#LAST#", "tformat")
t("Master which tool?", "どのツールにしますか？", "_t")
-- untranslated text
