section "mod-tome/data/general/traps/complex.lua"

t("complex", "機械系", "entity type")
t("trap", "罠", "_t")
t("boulder", "投石", "entity subtype")
t("giant boulder trap", "岩石カタパルト", "entity name")
t("@Target@ walks on a trap, and there is a loud noise.", "@Target@が罠を踏んだ。けたたましい音が上がる。", "_t")
t("large pressure plate", "大きなでっぱり", "_t")
t(" (from %s)", "（発射元方向　%s）", "tformat")
t("Releases a large boulder%s that smashes into the target for %d physical damage and knocks it back.", "　巨大な岩石%sを発射して対象を吹き飛ばし、物理属性の%dダメージを与えてノックバックさせる。", "tformat")
t("huge boulder", "巨大岩石", "_t")
t("arcane", "魔法", "entity subtype")
t("spinning beam trap", "回転ビーム", "entity name")
