section "mod-tome/dialogs/LevelupDialog.lua"

t("Levelup: %s, level %s", "レベルアップ：%s　レベル：%s", "tformat")
t("Finish", "決定", "_t")
t("Do you accept changes?", "　これでよろしいですか？", "_t")
t("Impossible", "外せない", "_t")
